"""Diecinueve historias comunitarias: alegría, descanso y cooperación cotidiana."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
personas=json.loads((ROOT/'datos/reparto.json').read_text());por_id={p['id']:p for p in personas}
encuentros=[]
def e(id,titulo,region,reparto,acciones,lineas,eleccion,ramas,premio='trofeo'):
    cast=reparto.split()
    encuentros.append(dict(id=id,titulo=titulo,asentamiento=region,reparto=cast,requiere=por_id[cast[0]]['mision']['requiere'],acciones=acciones.split(' / '),lineas=lineas,eleccion=eleccion,ramas=ramas.split(' / '),premio=premio,estado='diseno_no_integrado'))
e('E01','La olla y el baile','pueblo_sol','cocinero posadera musica artesana veterano',
'Preparar cuatro porciones con receta normal y cupos / Ensayar música y paso sentado o de pie / Reunir vecinos en cena breve sin obligar a actuar',
'cocinero: Preparé algo nuevo y algo conocido. Si todo es sorpresa, Rosa empieza a sospechar.\nposadera: Sospecho cuando el cocinero explica diez minutos antes de dejar probar.\nmusica: Traje una canción corta. Esta vez corta de verdad.\nartesana: Lo anoté como condición en el presupuesto.\nveterano: Yo puedo bailar sentado. Tiene la ventaja de que nadie me pisa.\nposadera: Aurelio, la última vez te pisaste tú solo.\ncocinero: ¿Les gustó? Pueden decir que no sin dar un discurso.\nartesana: Me gustó. Quiero repetir la parte donde nos sentamos.',
'Baile tranquilo o sobremesa de historias','musica: Dejaré sitio para mirar sin bailar. / posadera: Las historias serán voluntarias y el postre llegará igual.','plano')
e('E02','Una regata sin carrera','puerto_lirios','lirios_bastian lirios_belen lirios_tina lirios_julian lirios_teo',
'Dibujar barquitos pequeños con material recuperado / Probar en canal seguro con supervisión / Recoger todas las piezas y celebrar diseño, no velocidad',
'lirios_tina: ¿Por qué todos quieren que el barco llegue primero? El mío lleva una casa.\nlirios_bastian: Entonces tendrá que llegar cómodo.\nlirios_belen: Mi barco lleva una red que no pesca. Era más fácil de hacer.\nlirios_teo: El mío llegó de lado. Voy a llamarlo muelle.\nlirios_julian: Ganó el nombre, no la navegación.\nlirios_tina: Quiero que cada barco tenga una historia.\nlirios_bastian: Y que ninguno se quede en el río.\nlirios_belen: Las historias pueden flotar; la basura no se queda.',
'Exhibir dibujos o barquitos secos','lirios_tina: Los dibujos tienen más sitio para dragones. / lirios_bastian: Las piezas se guardarán sin ocupar el paso del muelle.','trofeo')
e('E03','El club de los sombreros feos','brumaverde','bruma_felix bruma_amira bruma_ada bruma_benicio bruma_roque',
'Reunir retazos y fibras del catálogo sin cortar bosque / Diseñar tres sombreros reutilizables / Celebrar muestra y devolver material sobrante',
'bruma_felix: El concurso tiene una regla: no admitiré sombreros discretos.\nbruma_amira: El mío lleva flores de tela. Las abejas no fueron invitadas a trabajar.\nbruma_ada: El mío parece un cerdo de musgo cansado.\nbruma_roque: Eso explica por qué tiene una almohada.\nbruma_benicio: Yo puedo contar que perteneció a un rey.\nbruma_ada: Primero di que te lo estás inventando.\nbruma_benicio: Me quitan toda la ceremonia. Está bien: perteneció a mí hace cinco minutos.\nbruma_felix: Tenemos ganador de historia. Falta decidir quién aguanta llevarlo.',
'Muestra pública o paseo corto','bruma_amira: Nadie tendrá que usar su sombrero si no le gusta. / bruma_roque: El paseo irá por sendero; las ramas no participarán del concurso.','plano')
e('E04','La sinfonía de herramientas quietas','piedralumbre','piedra_hugo piedra_petra piedra_mireya piedra_ciro herrero',
'Usar muestras inertes y herramientas fuera de operación / Ensayar tres patrones de ritmo con texto visible / Presentar pieza sin ruido de máquinas reales',
'piedra_hugo: Aquí está el ritmo escrito. Quien no lo oiga puede seguirlo igual.\npiedra_petra: Yo traje una piedra que suena horrible. Puede ser la solista.\npiedra_mireya: Si la conectamos...\nherrero: Hoy ninguna máquina va a hacer nuestro pasatiempo.\npiedra_ciro: Yo golpeo cucharas. Cuando acaben, sí vuelven a la cocina.\npiedra_petra: Bruno está afinando un clavo.\nherrero: Estoy comprobando que no haya punta. Afinar será problema de ustedes.\npiedra_hugo: Por fin tenemos una banda que puede detenerse sin alarma.',
'Interpretación breve o juego de patrones','piedra_ciro: Después servimos merienda sin tocar las ollas calientes. / piedra_hugo: El patrón podrá jugarse con fichas y sin audio.','trofeo')
e('E05','El mapa de las tazas','brasaviva','brasa_sol brasa_yago brasa_rufina brasa_tarek brasa_dante',
'Dibujar tazas de residentes con permiso / Clasificar uso y gusto sin concurso de perfección / Armar estante accesible o cuaderno de dibujos',
'brasa_yago: Esta taza tiene tres asas. ¿Quién tiene tres manos?\nbrasa_sol: Alguien que no pudo decidir dónde poner la primera.\nbrasa_rufina: La mía tiene una sola y se me pierde igual.\nbrasa_tarek: Yo quiero una grande para café.\nbrasa_dante: ¿Grande de verdad o grande de cuando cuentas tus viajes?\nbrasa_tarek: De verdad. Lo otro sería una piscina.\nbrasa_yago: Voy a dibujar esa también.\nbrasa_sol: El cuaderno permite tamaños que el horno no tiene que prometer.',
'Estante de piezas prestadas o álbum de dibujos','brasa_rufina: Los préstamos volverán a sus dueños. / brasa_yago: El álbum tendrá permiso para cada dibujo.','trofeo')
e('E06','Una merienda bajo techo','nieveclara','nieve_anselmo nieve_eira nieve_luz nieve_severo nieve_otto',
'Consultar clima y preparar comida ordinaria / Tejer pequeño tapete con lana existente / Compartir merienda en refugio sin viaje peligroso',
'nieve_severo: Hoy mi mejor pronóstico es que adentro hace más calor.\nnieve_anselmo: Está ganando precisión con los años.\nnieve_eira: Traje lana para un tapete, no para que me conviertan la tarde en pedido.\nnieve_luz: Yo traje un juego que no necesita luz de aurora.\nnieve_otto: ¿Necesita ganar?\nnieve_luz: No, pero voy a intentar.\nnieve_anselmo: Esa es una buena descripción de la tarde.\nnieve_eira: Y la última taza la lava alguien que no sea quien cocinó.',
'Juego de mesa o historias ligeras','nieve_luz: Las reglas tendrán dibujo y texto. / nieve_otto: Hoy ninguna historia tiene que terminar en rescate.','plano')
e('E07','La postal que no da noticias','vigilia','vigilia_telmo vigilia_noemi vigilia_ulises vigilia_azucena',
'Dibujar lugar seguro sin datos de guardia / Pedir permiso para postal colectiva / Enviar copia o exhibir sin nombres privados',
'vigilia_telmo: Quiero una postal que no empiece con lamentamos informarle.\nvigilia_noemi: Dibuja la cocina cuando no se quema nada.\nvigilia_ulises: Es un lugar difícil de documentar.\nvigilia_azucena: Yo propongo el cielo que vimos mientras no ocurría ninguna extracción.\nvigilia_telmo: ¿Y qué escribimos?\nvigilia_noemi: Hoy comimos bien y Ulises hizo un chiste malo.\nvigilia_ulises: No sé si eso sostiene una correspondencia.\nvigilia_azucena: A mí me gustaría recibirla.',
'Correo a destinatario consentido o panel de cocina','vigilia_telmo: No mostrará ubicación sensible ni listas de residentes. / vigilia_noemi: El panel también tendrá días corrientes, sin obligación de alegría.','trofeo')
e('E08','La receta de estar juntos','rosal_eterno','verdia_lucio verdia_amaranta verdia_yara verdia_tobias',
'Preparar encuentro sin necesidades corporales fingidas / Elegir sabor recordado o aroma con permiso / Conversar y recoger objetos de visita',
'verdia_lucio: No tienen que comer para vivir. Igual pueden opinar de mi sopa.\nverdia_amaranta: Esa libertad abre demasiadas posibilidades.\nverdia_tobias: Yo recuerdo otra textura.\nverdia_lucio: Perfecto. No hemos venido a ganar una investigación de sopa.\nverdia_yara: ¿Puedo cantar sobre eso?\nverdia_amaranta: Solo si es muy corta.\nverdia_tobias: Mi pez más grande era...\nverdia_lucio: La sopa se enfría en el relato, Tobías. Volvamos a la mesa.',
'Encuentro con canción o conversación sin música','verdia_yara: Cantaré solo después de preguntar. / verdia_lucio: La reunión no necesita otro motivo que querer compañía.','plano')
e('E09','El ensayo que se detiene','jardines_eco','eco_sora eco_esteban eco_basilia eco_oriel',
'Preparar pieza corta con permisos / Ensayar una pausa de entrada y salida / Presentar versión musical o lectura rítmica',
'eco_sora: Esta pieza tiene una pausa donde pueden salir.\neco_oriel: ¿Y si nadie sale?\neco_sora: Sigue siendo pausa. No vamos a expulsar a alguien para demostrar la idea.\neco_esteban: Me gusta una instrucción que admite que no ocurra nada.\neco_basilia: Traje luz pequeña, sin cuota de participación.\neco_oriel: Yo traje demasiadas preguntas.\neco_sora: Guárdanos una para la sobremesa.\neco_esteban: La anotaré como pregunta, no como conclusión del ensayo.',
'Pieza musical o ritmo en lectura','eco_sora: Nadie tiene que prestar voz a una grabación. / eco_esteban: La lectura tendrá puntuación y no dependerá del sonido.','trofeo')
e('E10','La tarde sin pruebas','travesia','senda_leire senda_iria senda_fabian senda_ofelia senda_pablo',
'Preparar zona de descanso autorizada / Separar provisiones de vivos de objetos simbólicos de almas / Elegir juego sin evaluación y permitir retiro',
'senda_leire: Hoy el juego no abre ninguna puerta.\nsenda_pablo: ¿Entonces cómo sé si lo hice bien?\nsenda_ofelia: Creo que esa es la pregunta que podemos dejar descansar.\nsenda_fabian: Las raciones son para quienes tienen cuerpo. Las fichas, para todos.\nsenda_iria: Y nadie tendrá que contar su reparación para jugar.\nsenda_pablo: Puedo perder una ronda sin perder el camino.\nsenda_leire: Exactamente.\nsenda_ofelia: Esto me gusta más de lo que esperaba.',
'Rompecabezas o paseo en zona segura','senda_iria: No tendrá respuestas morales ocultas. / senda_leire: El paseo tendrá ancla y podrá terminar antes.','agenda')
e('E11','Nudos que no atan','refugio_hilos','hilos_asha hilos_hector hilos_tecla hilos_elian',
'Usar cuerda de práctica distinta de anclas activas / Dibujar figuras abiertas / Guardar juego sin confundirlo con equipo de retorno',
'hilos_hector: Esta cuerda no es un ancla. Lo puse en dos etiquetas.\nhilos_asha: Yo puedo hacer un pez con ella.\nhilos_tecla: Desde cierto ángulo parece una ruta.\nhilos_elian: Desde este parece un fideo.\nhilos_asha: Por primera vez alguien mejoró mi descripción.\nhilos_hector: Les ruego no cocinar equipo de seguridad.\nhilos_tecla: Te estábamos esperando con ese chiste.\nhilos_elian: Quiero dejar la figura abierta. Se puede seguir mañana.',
'Figura abierta o juego de formas','hilos_asha: No la usaremos para sujetar a nadie ni activar rutas. / hilos_hector: Se guardará aparte del equipo real.','trofeo')
e('E12','El relevo y la comedia','bastion_velo','nox_dorian nox_salma nox_viggo nox_mirta nox_tamara',
'Confirmar cobertura de guardia sin abandonar protocolo / Preparar sala del perímetro con capacidad / Leer comedia autorizada sin acercarse a celdas',
'nox_dorian: El siguiente turno está cubierto. Podemos comenzar.\nnox_salma: Esa es una buena entrada para una comedia.\nnox_viggo: El cerrojo del decorado no abre.\nnox_mirta: Porque decidiste hacerlo funcional.\nnox_tamara: Lo más divertido va a ser salir del escenario.\nnox_dorian: Yo leo al personaje que pierde las llaves.\nnox_salma: Por favor, no uses las reales.\nnox_viggo: Ahora entiendo por qué piden utilería distinta.',
'Lectura breve o representación sentada','nox_mirta: El libreto no tendrá datos del servicio. / nox_tamara: El escenario mantendrá salidas claras y balizas sin apagar.','trofeo')
e('E13','La comida que no flota','estacion_celia','orbita_said orbita_dexo orbita_valentina orbita_rita',
'Preparar alimento con receta de estación / Confirmar sujeción de bandejas y reserva / Cenar en turno libre con manifiesto de limpieza',
'orbita_dexo: La última vez mi pan hizo órbita propia.\norbita_rita: Seguía registrado como carga, por supuesto.\norbita_valentina: Esta hoja viene de Celia. La siguiente tanda sí será del huerto.\norbita_said: Podemos comer sin convertir cada ingrediente en examen.\norbita_rita: Solo quiero saber qué tengo que sujetar.\norbita_dexo: Mi dignidad no pesa mucho; se me escapa igual.\norbita_valentina: La bandeja la salva.\norbita_said: Y hoy alguien diferente lavará los utensilios.',
'Mesa común o dos turnos','orbita_rita: La capacidad no cambiará porque invitemos a más gente. / orbita_said: Ambos turnos tendrán el mismo menú y descanso.','plano')
e('E14','El picnic con sombra','huerto_aurelia','aurelia_aitana aurelia_oscar aurelia_kiara aurelia_saul',
'Medir lugar seguro de luz / Reservar comida ordinaria y sombra / Compartir merienda sin ampliar recinto ecológico',
'aurelia_saul: Lo llamé picnic lunar y después recordé que todo aquí es lunar.\naurelia_oscar: Puedes llamarlo comida. Es una marca amplia.\naurelia_kiara: La sombra es para nosotros; la planta de ensayo queda en su sitio.\naurelia_aitana: Por una tarde acepto no comparar rendimientos.\naurelia_saul: ¿Comparar sabores sí?\naurelia_aitana: Eso siempre.\naurelia_oscar: La batería no dará premios por quedarse más tiempo.\naurelia_kiara: El descanso tampoco necesita darlos.',
'Sombra de tela o refugio existente','aurelia_aitana: La tela tendrá anclaje y se recogerá después. / aurelia_oscar: No gastaremos energía de retorno para iluminar la mesa.','trofeo')
e('E15','Cuentos del lado oscuro','vigia_nocturna','nocturna_matea nocturna_elvira nocturna_gaspar nocturna_naim',
'Reunir relatos declarados como ficción / Preparar luz de lectura sin afectar plantas / Leer dos historias y guardar instrumentos',
'nocturna_matea: Este cuento no sirve para navegar. Aviso antes de empezar.\nnocturna_gaspar: Mi monstruo es una lente que nunca necesita calibración.\nnocturna_elvira: El mío es una visita que enciende todas las luces.\nnocturna_naim: Yo traje un cuento feliz.\nnocturna_matea: Puedes hacerlo. El lado oscuro también tiene sobremesa.\nnocturna_gaspar: ¿Y qué ocurre?\nnocturna_naim: Todos terminan la jornada a tiempo.\nnocturna_elvira: Eso sí que parece fantástico.',
'Cuentos humorísticos o lectura tranquila','nocturna_matea: Ningún relato se archivará como fuente de rutas. / nocturna_elvira: La luz mantendrá refugio oscuro para las plantas.','trofeo')
e('E16','Un dibujo de lo pequeño','cantera_esmeralda','esmeralda_olmo esmeralda_indira esmeralda_duna esmeralda_raimundo',
'Observar muestras autorizadas sin extracción extra / Dibujar detalles con escala / Armar lámina común y devolver piezas',
'esmeralda_duna: Parece un bosque si acerco mucho el dibujo.\nesmeralda_olmo: Es una muestra. No le cobres arriendo a ningún árbol.\nesmeralda_indira: Puedo ponerle ritmo a la forma.\nesmeralda_raimundo: Y yo puedo ponerle escala para que no pidan una excavadora.\nesmeralda_duna: ¿Todo tiene que ser informe?\nesmeralda_raimundo: No. Por eso la escala va atrás.\nesmeralda_olmo: Adelante pueden caber todos los bosques imaginados.\nesmeralda_indira: Sin factura de extracción.',
'Lámina artística o ficha comparativa','esmeralda_duna: La portada dirá dibujo, no hábitat real. / esmeralda_raimundo: La ficha conservará escala y procedencia.','conocimiento')
e('E17','El museo de cosas inútiles','campamento_fragmentos','fragmentos_axel fragmentos_pia fragmentos_lazaro fragmentos_uma',
'Identificar restos sin dueño pendiente de restitución / Crear pieza decorativa con costo real / Exponer sin registrar material ficticio recuperado',
'fragmentos_lazaro: No son inútiles. Todavía podrían servir.\nfragmentos_uma: Esa pieza no gira desde antes de que yo llegara.\nfragmentos_pia: Sirve para que la luz haga esto.\nfragmentos_axel: Entonces el museo tiene una función y perdió el nombre.\nfragmentos_lazaro: Podríamos llamarlo cosas que no tienen que salvarnos.\nfragmentos_uma: Me gusta mucho más.\nfragmentos_pia: Esta sí tenía dueño. La dejaremos fuera de la muestra.\nfragmentos_axel: Y con destino de devolución, no olvido.',
'Objeto pequeño o dibujo del conjunto','fragmentos_lazaro: No devolverá materiales al venderse; no está en venta. / fragmentos_pia: El dibujo no reemplazará recibos de restitución.','trofeo')
e('E18','La sombra de una conversación','ambarina','ambar_zora ambar_alina ambar_baltasar ambar_samira ambar_kenzo',
'Contar agua y asientos de encuentro / Preparar té con ingredientes disponibles / Conversar en sombra y registrar gasto sin auditoría de afectos',
'ambar_zora: Hay agua para cinco tazas y una de reserva.\nambar_baltasar: ¿La reserva también viene a conversar?\nambar_alina: La sexta taza se sienta donde quiera.\nambar_samira: Pronostico chistes secos durante la tarde.\nambar_kenzo: El mío es antiguo y puede consultarse sin llevárselo.\nambar_zora: Quiero una conversación que no termine en tratado.\nambar_baltasar: Podemos hablar de tu cerámica.\nambar_zora: Ahora sí vamos a discutir.',
'Mesa de dibujos o sobremesa libre','ambar_kenzo: Los dibujos conservarán permiso de sus autores. / ambar_zora: No habrá acta de lo que cada persona decidió callar.','agenda')
e('E19','El cristal que desafina a propósito','iridalia','iris_orin iris_calista iris_liora iris_edda iris_mauro iris_yuna',
'Usar instrumento existente sin retirar cristal / Ensayar ritmo con pausas y volumen autorizado / Celebrar encuentro con salida de fauna y visitantes separada',
'iris_orin: Esta nota la puse mal a propósito.\niris_liora: Es igual a la que pusiste mal ayer sin propósito.\niris_calista: No voy a convocar una votación sobre eso.\niris_edda: El volumen está bien desde el nido. Pueden continuar.\niris_mauro: Yo traje un paso de baile terrestre.\niris_yuna: ¿Eso también necesita recinto de prueba?\niris_orin: Solo si Mauro decide girar otra vez.\niris_mauro: Me retiro de la demostración con dignidad reducida, pero intacto.',
'Música breve o juego rítmico sin audio','iris_orin: La pieza no afirmará que el planeta aprobó nada. / iris_yuna: Las fichas permitirán participar sin escuchar ni bailar.','trofeo')
(ROOT/'datos/encuentros.json').write_text(json.dumps(encuentros,ensure_ascii=False,indent=2)+'\n')
print(f'{len(encuentros)} misiones comunitarias dialogadas')
